CREATE TABLE IF NOT EXISTS public."COMPONENTLICENSES" (
    "ID" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "COMPONENTID" bigint NOT NULL,
    "LICENSE_ID" bigint,
    "LICENSE" text,
    "LICENSE_EXPRESSION" text,
    "LICENSE_URL" text,
    "ORDINALITY" bigint NOT NULL CHECK ("ORDINALITY" > 0),
    "CONCLUDED" boolean DEFAULT false NOT NULL,
    CONSTRAINT "COMPONENTLICENSES_FK1" FOREIGN KEY ("COMPONENTID") REFERENCES public."COMPONENT"("ID"),
    CONSTRAINT "COMPONENTLICENSES_FK2" FOREIGN KEY ("LICENSE_ID") REFERENCES public."LICENSE"("ID")
);

INSERT INTO public."COMPONENTLICENSES" (
    "COMPONENTID",
    "LICENSE_ID",
    "LICENSE",
    "LICENSE_EXPRESSION",
    "LICENSE_URL",
    "ORDINALITY",
    "CONCLUDED"
) SELECT "ID", "LICENSE_ID", "LICENSE", "LICENSE_EXPRESSION", "LICENSE_URL", 1, false FROM public."COMPONENT";

-- squawk-ignore require-concurrent-index-creation
CREATE UNIQUE INDEX IF NOT EXISTS "COMPONENTLICENSES_ID_UQ"
    ON "COMPONENTLICENSES" ("COMPONENTID", "LICENSE_ID")
    WHERE "LICENSE_ID" IS NOT NULL;

-- squawk-ignore require-concurrent-index-creation
CREATE UNIQUE INDEX IF NOT EXISTS "COMPONENTLICENSES_EXP_UQ"
    ON "COMPONENTLICENSES" ("COMPONENTID", "LICENSE_EXPRESSION")
    WHERE "LICENSE_EXPRESSION" IS NOT NULL;

ALTER TABLE public."COMPONENT" 
    DROP CONSTRAINT IF EXISTS "COMPONENT_LICENSE_FK",
    -- squawk-ignore ban-drop-column
    DROP COLUMN IF EXISTS "LICENSE_ID",
    -- squawk-ignore ban-drop-column
    DROP COLUMN IF EXISTS "LICENSE",
    -- squawk-ignore ban-drop-column
    DROP COLUMN IF EXISTS "LICENSE_EXPRESSION",
    -- squawk-ignore ban-drop-column
    DROP COLUMN IF EXISTS "LICENSE_URL";

-- squawk-ignore require-concurrent-index-creation
CREATE INDEX IF NOT EXISTS "COMPONENTLICENSES_COMPONENT_ORDINALITY_IDX"
    ON public."COMPONENTLICENSES" ("COMPONENTID", "ORDINALITY");